struct MilitaryRead final:MilitaryTacticKnowledgeRead {
 const CommonStore& c;bool qualified=true,student_known=false;explicit MilitaryRead(const CommonStore& common):c(common){}
 Outcome<MilitaryTacticTeachingTarget> tactic_definition(const StableId& tactic)const override{return {true,{c.state().identity,tactic,"rally","tactics",1,{"teacher"}}, {}};}
 Outcome<std::optional<MilitaryTacticLearningObservation>> value(const StableId& actor,const StableId& tactic,Integer tick,const StableId& before)const{
  if(!qualified||(actor=="student"&&!student_known))return {true,std::nullopt,{}};MilitaryTacticLearningObservation p;p.source_identity=c.state().identity;p.actor_id=actor;p.tactic_id=tactic;p.acquisition_fact_id="military_tactic:2";p.source_fact_id="initial_teacher";p.initial_grant_id="initial_teacher";p.source_kind=MilitaryTacticLearningSourceKind::authored_initial;p.acquired_tick=0;p.observed_tick=tick;p.before_fact_id=before;return {true,p,{}};
 }
 Outcome<std::optional<MilitaryTacticLearningObservation>> current_tactic(const StableId& actor,const StableId& tactic)const override{return value(actor,tactic,c.tick(),{});}
 Outcome<std::optional<MilitaryTacticLearningObservation>> tactic_before(const StableId& actor,const StableId& tactic,Integer tick,const StableId& before)const override{return value(actor,tactic,tick,before);}
};
